package in.kpmaster.mobile;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.provider.Settings;import android.print.*;import android.webkit.*;import android.widget.*;import android.view.*;import android.util.Base64;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;

public final class MainActivity extends Activity {
 private static final String ORIGIN="https://kp-master.invalid/";private static final int OPEN=101,SAVE=102,LICENSE=103,CONTROL=104,RESTORE=105;
 private WebView main;private LinearLayout root;private LicenseManager licences;private DemoManager demo;private String identity,error="";private ValueCallback<Uri[]> chooser;private byte[] pendingSave;private final List<Dialog> popups=new ArrayList<>();private final Map<WebView,Dialog> reports=new HashMap<>();private final Handler clock=new Handler(Looper.getMainLooper());
 private String read(InputStream in,int limit)throws Exception{try(InputStream s=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=s.read(b))!=-1){if(out.size()+n>limit)throw new Exception("File is too large.");out.write(b,0,n);}return out.toString("UTF-8");}}
 @Override public void onCreate(Bundle state){super.onCreate(state);try{
  android.content.pm.PackageInfo engine=WebView.getCurrentWebViewPackage();if(engine==null||Integer.parseInt(engine.versionName.split("\\.")[0])<110){root=layout();TextView message=new TextView(this);message.setText("KP MASTER needs an updated Android System WebView. Update or enable it, then reopen the app. Your calculations work offline after setup.");message.setPadding(28,28,28,28);root.addView(message);root.addView(button("Update Android System WebView",()->external("https://play.google.com/store/apps/details?id=com.google.android.webview")));root.addView(button("Retry",this::recreate));return;}
  String id=Settings.Secure.getString(getContentResolver(),Settings.Secure.ANDROID_ID);if(id==null||id.length()<8||id.matches("0+"))throw new Exception("A stable Android device ID is unavailable.");
  identity=systemId(id);licences=new LicenseManager(this,identity);demo=new DemoManager(this,identity);showApp();
 }catch(Exception e){error=e.getMessage();showGate();}
 clock.postDelayed(new Runnable(){public void run(){if(!BuildConfig.OWNER&&main!=null){try{requireAccess();}catch(Exception e){error=e.getMessage();showGate();}}clock.postDelayed(this,60000);}},60000);
 }
 static String systemId(String androidId)throws Exception{
  MessageDigest hash=MessageDigest.getInstance("SHA-256");String guid=hex(hash.digest(new JSONArray(Arrays.asList("android",BuildConfig.APP_ID,androidId)).toString().getBytes(StandardCharsets.UTF_8))).substring(0,32);
  String digest=hex(hash.digest(new JSONArray(Arrays.asList("kp-master-offline",1,guid,"")).toString().getBytes(StandardCharsets.UTF_8))).substring(0,32).toUpperCase(java.util.Locale.ROOT);
  return "KP1-"+digest.replaceAll("(.{4})(?!$)","$1-");
 }
 private static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return out.toString();}
 private LinearLayout layout(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setBackgroundColor(Color.WHITE);l.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(l);return l;}
 private void clear(){for(Dialog d:new ArrayList<>(popups))d.dismiss();popups.clear();if(main!=null){main.removeJavascriptInterface("KPAndroid");main.stopLoading();main.destroy();main=null;}}
 private Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setOnClickListener(v->action.run());return b;}
 private void requireAccess()throws Exception{try{licences.active();}catch(Exception e){if(licences.hasStoredLicence())throw e;demo.status();}}
 private boolean paid(){try{licences.active();return true;}catch(Exception e){return false;}}
 private void showGate(){clear();root=layout();ScrollView scroll=new ScrollView(this);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(28,28,28,28);scroll.addView(card);root.addView(scroll,new LinearLayout.LayoutParams(-1,-1));
  TextView heading=new TextView(this);heading.setText("KP MASTER · Customer\nActivate this phone");heading.setTextSize(24);heading.setTextColor(Color.rgb(22,65,89));card.addView(heading);
  TextView hint=new TextView(this);hint.setText("Demo: 15 kundali calculations and 10 matchmaking calculations. Send this System ID to the owner. Enter the registration key first, then the separate purchase key for full use. Registration does not reset demo credits.");card.addView(hint);
  TextView id=new TextView(this);id.setText(identity==null?"System ID unavailable":identity);id.setTextIsSelectable(true);id.setTextSize(17);id.setPadding(0,22,0,22);card.addView(id);
  card.addView(button("Copy System ID",()->{if(identity!=null){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("KP MASTER System ID",identity));toast("System ID copied.");}}));
  card.addView(button("Enter registration / purchase key",this::enterKey));
  if(licences!=null&&!licences.hasStoredLicence())card.addView(button("Continue available demo",this::showApp));
  card.addView(button("Save System ID file",()->{try{save(licences.request().getBytes(StandardCharsets.UTF_8),"KP-MASTER-Android-System-ID.txt","text/plain");}catch(Exception e){toast(e.getMessage());}}));
  card.addView(button("Import activation licence",()->openDocument(LICENSE)));
  card.addView(button("Import Activate / Deactivate status",()->openDocument(CONTROL)));card.addView(button("Activate / Open software",this::showApp));
  TextView status=new TextView(this);status.setText(error);status.setTextColor(Color.rgb(155,35,35));status.setPadding(0,16,0,16);card.addView(status);
 }
 private void enterKey(){
  EditText field=new EditText(this);field.setHint("Paste KP-R1 registration, KP-A1 purchase or KP-S1 status key");field.setMinLines(4);field.setMaxLines(7);field.setGravity(Gravity.TOP);field.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(16384)});
  LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(24,12,24,12);box.addView(field);
  AlertDialog d=new AlertDialog.Builder(this).setTitle("Customer activation key").setView(box).setPositiveButton("Activate / Apply",null).setNeutralButton("Paste",null).setNegativeButton("Cancel",null).create();
  d.setOnShowListener(v->{d.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(x->{android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(c.hasPrimaryClip()&&c.getPrimaryClip().getItemCount()>0)field.setText(c.getPrimaryClip().getItemAt(0).coerceToText(this));});d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{try{String code=field.getText().toString();boolean status=code.replaceAll("\\s", "").startsWith("KP-S1.");String text=LicenseManager.codeEnvelope(code,status);if(status)licences.importControl(text);else {boolean purchased=licences.importKey(text);if(!purchased)toast("Registration saved. Enter the separate purchase key to unlock full use.");}d.dismiss();showApp();}catch(Exception e){field.setError(e.getMessage());}});});d.show();
 }
 private void showApp(){if(!BuildConfig.OWNER){try{requireAccess();}catch(Exception e){error=e.getMessage();showGate();return;}}clear();root=layout();LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView title=new TextView(this);title.setText("KP MASTER · "+(BuildConfig.OWNER?"Owner":"Customer"));title.setTextColor(Color.rgb(22,65,89));title.setPadding(14,4,4,4);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("☰",this::menu));root.addView(bar);main=webView(false);root.addView(main,new LinearLayout.LayoutParams(-1,0,1));main.loadUrl(ORIGIN+"index.html");}
 private void menu(){PopupMenu p=new PopupMenu(this,root.getChildAt(0));p.getMenu().add("Single-page Kundali PDF");p.getMenu().add("Print / Save PDF");p.getMenu().add("Zoom +");p.getMenu().add("Zoom −");p.getMenu().add("Backup app data");p.getMenu().add("Restore backup");if(!BuildConfig.OWNER){p.getMenu().add("Enter Activate / Deactivate key");p.getMenu().add("Import licence status");p.getMenu().add("System ID");}p.setOnMenuItemClickListener(i->{String s=i.getTitle().toString();if(s.equals("Single-page Kundali PDF"))main.evaluateJavascript("KPMobile.singlePagePDF()",null);else if(s.equals("Print / Save PDF"))print(main);else if(s.equals("Zoom +"))main.getSettings().setTextZoom(Math.min(180,main.getSettings().getTextZoom()+10));else if(s.equals("Zoom −"))main.getSettings().setTextZoom(Math.max(70,main.getSettings().getTextZoom()-10));else if(s.equals("Backup app data"))main.evaluateJavascript("KPMobile.backup()",null);else if(s.equals("Restore backup"))openDocument(RESTORE);else if(s.equals("Enter Activate / Deactivate key"))enterKey();else if(s.equals("Import licence status"))openDocument(CONTROL);else toast(identity);return true;});p.show();}
 private WebView webView(boolean popup){WebView w=new WebView(this);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setCacheMode(WebSettings.LOAD_NO_CACHE);s.setDomStorageEnabled(true);s.setSupportMultipleWindows(true);s.setJavaScriptCanOpenWindowsAutomatically(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setUseWideViewPort(true);s.setLoadWithOverviewMode(popup);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);s.setMediaPlaybackRequiresUserGesture(true);w.addJavascriptInterface(new Bridge(w,popup),"KPAndroid");
  w.setWebViewClient(new WebViewClient(){
   @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri u=request.getUrl();if("GET".equals(request.getMethod())&&"https".equals(u.getScheme())&&"kp-master.invalid".equals(u.getHost())){String path=u.getPath();String file=path==null||path.equals("/")?"index.html":path.substring(1);if(!file.contains("..")&&!file.contains("\\")){try{return new WebResourceResponse(file.endsWith(".js")?"application/javascript":file.endsWith(".json")?"application/json":"text/html","UTF-8",getAssets().open(file));}catch(Exception ignored){}}}return new WebResourceResponse("text/plain","UTF-8",403,"Blocked",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
   @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String u=request.getUrl().toString();if(u.startsWith(ORIGIN)||u.equals("about:blank"))return false;if(request.hasGesture())external(u);return true;}
   @Override public void onPageFinished(WebView view,String url){if(url.startsWith(ORIGIN)||popup&&url.equals("about:blank"))try{String js=read(getAssets().open("mobile.js"),1048576);view.evaluateJavascript(js,null);}catch(Exception e){toast(e.getMessage());}}
  });
  w.setWebChromeClient(new WebChromeClient(){
   @Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams options){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,options.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);startActivityForResult(i,OPEN);return true;}
   @Override public boolean onCreateWindow(WebView view,boolean dialog,boolean gesture,Message result){if(!BuildConfig.OWNER)try{requireAccess();}catch(Exception e){return false;}Dialog d=new Dialog(MainActivity.this);LinearLayout l=new LinearLayout(MainActivity.this);l.setOrientation(1);WebView report=webView(true);LinearLayout tools=new LinearLayout(MainActivity.this);tools.addView(button("Print / Save PDF",()->print(report)));tools.addView(button("Close",d::dismiss));tools.addView(button("Zoom +",()->report.zoomIn()));tools.addView(button("Zoom −",()->report.zoomOut()));HorizontalScrollView toolScroll=new HorizontalScrollView(MainActivity.this);toolScroll.addView(tools);l.addView(toolScroll);l.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});l.addView(report,new LinearLayout.LayoutParams(-1,0,1));d.setContentView(l);d.setOnDismissListener(x->{report.removeJavascriptInterface("KPAndroid");report.stopLoading();report.destroy();popups.remove(d);reports.remove(report);});popups.add(d);reports.put(report,d);d.show();d.getWindow().setLayout(-1,-1);((WebView.WebViewTransport)result.obj).setWebView(report);result.sendToTarget();return true;}
   @Override public void onCloseWindow(WebView view){Dialog d=reports.get(view);if(d!=null)d.dismiss();}
  });return w;
 }
 private void external(String url){try{Uri u=Uri.parse(url);if(Arrays.asList("https","mailto","tel").contains(u.getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){toast("No app can open this link.");}}
 private void toast(String text){Toast.makeText(this,text==null?"Unable to complete action.":text,Toast.LENGTH_LONG).show();}
 private void print(WebView w){if(w==null)return;w.evaluateJavascript("Promise.resolve(window.KPMobile?KPMobile.preparePrint():true).then(ready=>{if(!ready)return;return Promise.resolve(document.fonts?document.fonts.ready:null).then(()=>{window.dispatchEvent(new Event('beforeprint'));requestAnimationFrame(()=>requestAnimationFrame(()=>KPAndroid.readyToPrint()));});})",null);}
 private void printReady(WebView w){PrintManager manager=(PrintManager)getSystemService(PRINT_SERVICE);manager.print("KP MASTER report",w.createPrintDocumentAdapter("KP MASTER"),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).setColorMode(PrintAttributes.COLOR_MODE_COLOR).setMinMargins(PrintAttributes.Margins.NO_MARGINS).build());}
 private void openDocument(int code){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),code);}
 private void save(byte[] data,String name,String mime){if(pendingSave!=null){toast("Finish the current file save first.");return;}pendingSave=data;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name),SAVE);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);Uri uri=data==null?null:data.getData();try{
  if(request==OPEN){if(chooser!=null){Uri[] files=null;if(result==RESULT_OK){if(uri!=null)files=new Uri[]{uri};else if(data!=null&&data.getClipData()!=null){ClipData c=data.getClipData();files=new Uri[Math.min(c.getItemCount(),32)];for(int i=0;i<files.length;i++)files[i]=c.getItemAt(i).getUri();}}chooser.onReceiveValue(files);chooser=null;}}
  else if(request==SAVE){if(result==RESULT_OK&&uri!=null&&pendingSave!=null)try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(pendingSave);toast("File saved.");}pendingSave=null;}
  else if(request==RESTORE&&result==RESULT_OK&&uri!=null&&main!=null){String text=read(getContentResolver().openInputStream(uri),16*1024*1024);main.evaluateJavascript("KPMobile.restoreData("+JSONObject.quote(text)+")",null);}
  else if((request==LICENSE||request==CONTROL)&&result==RESULT_OK&&uri!=null){String text=read(getContentResolver().openInputStream(uri),16384);if(request==LICENSE)licences.importKey(text);else licences.importControl(text);showApp();}
 }catch(Exception e){pendingSave=null;error=e.getMessage();if(request==LICENSE||request==CONTROL)showGate();else toast(error);}}
 final class Bridge {
  private final WebView view;private final boolean popup;Bridge(WebView v,boolean p){view=v;popup=p;}
  private boolean trusted(){String u=view.getUrl();return u!=null&&(u.startsWith(ORIGIN)||popup&&u.equals("about:blank"));}
  @JavascriptInterface public String featureStatus(){try{if(!trusted())throw new Exception("Untrusted feature request.");JSONObject c=null;if(!BuildConfig.OWNER){try{c=licences.active();}catch(Exception e){if(licences.hasStoredLicence())throw e;demo.status();}}return new JSONObject().put("features",c!=null&&c.has("features")?c.getJSONArray("features"):licences.featureIds()).put("edition",c==null?"Full":c.optString("edition","Full")).toString();}catch(Exception e){return "{\"features\":[],\"edition\":\"Locked\"}";}}
  @JavascriptInterface public String demoStatus(){try{if(!trusted())throw new Exception("Untrusted demo request.");if(BuildConfig.OWNER||paid())return new JSONObject().put("paid",true).toString();if(licences.hasStoredLicence())throw new Exception("Purchase activation is required.");return demo.status().put("registered",licences.isRegistered()).toString();}catch(Exception e){return "{\"allowed\":false,\"error\":\"Activation or verified demo data is required.\"}";}}
  @JavascriptInterface public String demoUse(String kind,String signature,boolean consume){try{if(!trusted())throw new Exception("Untrusted demo request.");if(BuildConfig.OWNER||paid())return new JSONObject().put("allowed",true).put("paid",true).toString();if(licences.hasStoredLicence())throw new Exception("Purchase activation is required.");return demo.use(kind,signature,consume).put("registered",licences.isRegistered()).toString();}catch(Exception e){return "{\"allowed\":false,\"error\":\"Activation or verified demo data is required.\"}";}}
  @JavascriptInterface public void registerDemo(){runOnUiThread(()->{if(trusted())showGate();});}
  @JavascriptInterface public void readyToPrint(){runOnUiThread(()->{if(trusted())printReady(view);});}
  @JavascriptInterface public void saveSinglePageKundali(){runOnUiThread(()->{if(trusted()&&main!=null)main.evaluateJavascript("KPMobile.singlePagePDF()",null);});}
  @JavascriptInterface public void printReport(){runOnUiThread(()->{if(trusted())print(view);});}
  @JavascriptInterface public void shareFile(String name,String mime,String base64){runOnUiThread(()->{if(!trusted())return;try{if(!BuildConfig.OWNER){requireAccess();if(paid()){JSONObject claims=licences.active();if(claims.has("features")&&!claims.getJSONArray("features").toString().contains("\"reports\""))throw new Exception("Reports are not included in this package.");}}if(!"application/pdf".equals(mime)||base64==null||base64.length()>24*1024*1024||!base64.matches("[A-Za-z0-9+/]*={0,2}"))throw new Exception("This report is too large or invalid.");byte[] bytes=Base64.decode(base64,Base64.DEFAULT);if(bytes.length<5||bytes[0]!='%'||bytes[1]!='P'||bytes[2]!='D'||bytes[3]!='F')throw new Exception("Choose a PDF report.");String safe=(name==null?"KP-MASTER-Report":name).replaceAll("[^\\p{L}\\p{N}._ -]","_").replaceAll("(?i)\\.pdf$","");if(safe.length()>80)safe=safe.substring(0,80);if(safe.isEmpty())safe="KP-MASTER-Report";safe+=".pdf";String token=UUID.randomUUID().toString();File folder=new File(new File(getCacheDir(),"shared-reports"),token);if(!folder.mkdirs())throw new Exception("Cannot prepare the report.");try(FileOutputStream out=new FileOutputStream(new File(folder,safe))){out.write(bytes);}Uri uri=new Uri.Builder().scheme("content").authority(getPackageName()+".share").appendPath(token).appendPath(safe).build();Intent share=new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,uri).putExtra(Intent.EXTRA_SUBJECT,"KP MASTER report").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);share.setClipData(ClipData.newRawUri("KP MASTER report",uri));for(String app:new String[]{"com.whatsapp","com.whatsapp.w4b"}){share.setPackage(app);if(share.resolveActivity(getPackageManager())!=null){startActivity(share);return;}}share.setPackage(null);startActivity(Intent.createChooser(share,"Share report · WhatsApp"));}catch(Exception e){toast(e.getMessage());}});}
  @JavascriptInterface public void saveFile(String name,String mime,String base64){runOnUiThread(()->{if(!trusted())return;try{if(base64==null||base64.length()>24*1024*1024||!base64.matches("[A-Za-z0-9+/]*={0,2}"))throw new Exception("This export is too large or invalid.");String safe=(name==null?"KP-MASTER-backup.txt":name).replaceAll("[^\\p{L}\\p{N}._ -]","_");if(safe.length()>100)safe=safe.substring(0,100);String type=mime!=null&&mime.matches("[a-zA-Z0-9.+-]+/[a-zA-Z0-9.+-]+")?mime:"application/octet-stream";save(Base64.decode(base64,Base64.DEFAULT),safe,type);}catch(Exception e){toast(e.getMessage());}});}
 }
 @Override protected void onResume(){super.onResume();if(!BuildConfig.OWNER&&main!=null)try{requireAccess();}catch(Exception e){error=e.getMessage();showGate();}}
 @Override public void onBackPressed(){if(!popups.isEmpty()){popups.get(popups.size()-1).dismiss();return;}if(main!=null&&main.canGoBack())main.goBack();else super.onBackPressed();}
 @Override protected void onDestroy(){clock.removeCallbacksAndMessages(null);if(chooser!=null)chooser.onReceiveValue(null);clear();super.onDestroy();}
}
